{
  "diagnosis": "F43.23",
  "candidates": ["F32.9", "F41.9", "R41.840"],
  "reason": "Symptoms began within about 1 month of a clear work-related psychosocial stressor and the patient links the mood/cognitive changes to that stressor. He has mixed depressive symptoms with some anxiety/rumination and insomnia, causing work impairment. Although a depressive episode was considered, persistent depressed mood nearly every day was not clearly established, making adjustment disorder with mixed anxiety and depressed mood the best fit from the candidates.",
  "diagnostic_checklist": {
    "symptom_groups": [
      {
        "group": "psychosocial_stressor_related_onset",
        "confirmed_symptoms": [
          "clinic lost staff, schedule shifted to late-evening coverage, and crisis paperwork increased",
          "symptoms started around the time of these work changes about 1 month ago",
          "patient believes he probably would not be feeling this way in the same way without the work changes"
        ],
        "count": 3
      },
      {
        "group": "depressive_symptoms",
        "confirmed_symptoms": [
          "reduced interest/enjoyment in guitar, soccer, volunteer shelter shifts, cooking, and hiking",
          "feeling low/flattened/heavy many days",
          "decreased appetite with skipped meals and looser pants suggesting weight loss",
          "insomnia with difficulty falling asleep and early awakening",
          "feelings of worthlessness/excessive self-criticism about minor work mistakes",
          'passive death thoughts such as "if I just did not wake up, maybe that would be easier," without plan'
        ],
        "count": 6
      },
      {
        "group": "anxiety_tension_symptoms",
        "confirmed_symptoms": [
          "feels keyed up at moments",
          "replays the day in bed and thinks about tomorrow",
          "mental overactivity/ruminative thought flow"
        ],
        "count": 3
      },
      {
        "group": "cognitive_concentration_symptoms",
        "confirmed_symptoms": [
          "loses track of what clients are saying at work",
          "reads the same line repeatedly in chart notes",
          "freezes on simple decisions that used to be easy"
        ],
        "count": 3
      }
    ],
    "duration_verified": "Symptoms have been present most days for about 1 month, clearly more than 2 weeks, beginning after the work stressor.",
    "functional_impairment": true,
    "traumatic_stressor": null,
    "psychosocial_stressor": true,
    "additional_requirements": [
      "Symptoms are temporally related to an identifiable non-traumatic psychosocial stressor",
      "Reaction appears disproportionate to the stressor by patient's report",
      "No suicidal plan or intent reported"
    ]
  }
}

